import json,re,hashlib
from pathlib import Path
from collections import Counter
root=Path.cwd(); p=root/'content/isc2-cc-2026/sources/domain-5/production'; out=root/'docs/plans/isc2-cc-2026'; qa=root/'artifacts/qa/domain5-production'
ds=json.loads((p/'drafts.json').read_text(encoding='utf8')); good=[d for d in ds if d['status']!='REJECTED']; k=json.loads((p/'knowledge.json').read_text(encoding='utf8'))
def write(name,s):(out/('domain-5-production-'+name+'.md')).write_text(s+'\n',encoding='utf8')
inventory=(out/'domain-5-audit-source-inventory.md').read_text(encoding='utf8')
images={m[0]:m[1] for m in re.findall(r'\| (I\d\d) \| `([^`]+)`',inventory)}
def evidence(d):
 result=[]; src=d['source']
 for m in re.finditer(r'T:?\s*(\d+)(?:[–-](\d+))?',src):result.append(dict(path='ISC2 Update 2026/Domain 5/DOMAIN 5.txt',lines=[int(m[1]),int(m[2] or m[1])]))
 for a,b in re.findall(r'I(\d\d)(?:[–-]I?(\d\d))?',src):
  for i in range(int(a),int(b or a)+1):
   code=f'I{i:02}';result.append(dict(code=code,path='ISC2 Update 2026/Domain 5/'+images[code]))
 for r in result:r['sha256']=hashlib.sha256((root/r['path']).read_bytes()).hexdigest()
 return result
manifest=[]
for d in ds:
 manifest.append({**{f:d[f] for f in ['id','authoringId','family','objective','knowledge','cognitive','difficulty','stemType','assessedDecision','ambiguityControl','misconceptionTarget','references','source','revision','status']},'sourceEvidence':evidence(d),'draftPath':str(p.relative_to(root)/'drafts.json'),'productionPath':'data/certs/isc2/cc/versions/next-bank/questions/domain-5.js' if d['status']!='REJECTED' else None})
(p/'authoring-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
